function minimumOperations(nums) {
  const values = nums.slice();
  let operations = 0;
  for (;;) {
    const positive = values.filter(v => v > 0);
    if (positive.length === 0) return operations;
    const x = Math.min(...positive);
    for (let i = 0; i < values.length; i++) if (values[i] > 0) values[i] -= x;
    operations++;
  }
}

